cat >> src/boxOffice.test.ts <<'EOF'

const MINUTE = 60_000;

function setup(overrides: Partial<BoxOfficeOptions> = {}) {
  const clock = { time: 1_000_000 };
  const office = createBoxOffice({
    sections: [
      { id: "PARKETT", capacity: 10, priceCents: 4990 },
      { id: "BALKON", capacity: 5, priceCents: 3000 },
    ],
    holdMinutes: 15,
    maxTicketsPerCustomer: 6,
    now: () => clock.time,
    ...overrides,
  });
  return { office, clock };
}

function codeOf(fn: () => unknown): string | undefined {
  try {
    fn();
  } catch (error) {
    if (error instanceof BoxOfficeError) return error.code;
    throw error;
  }
  return undefined;
}

describe("box office", () => {
  test("available returns the capacity of a fresh section", () => {
    const { office } = setup();
    expect(office.available("PARKETT")).toBe(10);
  });
});
EOF
sed -i 's|import { BoxOfficeError } from "./boxOffice";|import { BoxOfficeError, createBoxOffice, type BoxOfficeOptions } from "./boxOffice";|' src/boxOffice.test.ts
bun test 2>&1 | tail -15

python3 - <<'EOF'
p='src/boxOffice.ts'
s=open(p).read()
start=s.index('export function createBoxOffice')
s=s[:start]+'''export function createBoxOffice(options: BoxOfficeOptions): BoxOffice {
  const holds: Hold[] = [];

  return {
    hold(customerId, sectionId, quantity) {
      const hold: Hold = {
        holdId: `H${holds.length + 1}`,
        customerId,
        sectionId,
        quantity,
        expiresAt: options.now() + options.holdMinutes * 60_000,
      };
      holds.push(hold);
      return { ...hold };
    },
    confirm() {
      throw new Error("Not implemented");
    },
    release() {
      throw new Error("Not implemented");
    },
    cancelOrder() {
      throw new Error("Not implemented");
    },
    available(sectionId) {
      const capacity = options.sections.find((s) => s.id === sectionId)!.capacity;
      const held = holds
        .filter((h) => h.sectionId === sectionId)
        .reduce((sum, h) => sum + h.quantity, 0);
      return capacity - held;
    },
  };
}
'''
open(p,'w').write(s)
EOF
